.device-summary{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:10px;margin:14px 0}
.device-summary div{padding:13px;border-radius:14px;border:1px solid var(--line);background:rgba(148,163,184,.08)}
.device-table{min-width:860px}
.device-table td:first-child{min-width:250px}.device-table td:nth-child(2){min-width:360px}
.device-note{color:var(--muted);font-size:12px;line-height:1.5;margin-top:5px}
.device-placeholder{color:var(--blue);font-size:12px;font-weight:800;margin-top:6px}


/* v9 expandable hierarchy navigation */
.sidebar{overflow:auto}
.nav-tree{display:grid;gap:7px;margin-top:8px}
.tree-section{border:1px solid var(--line);border-radius:16px;background:rgba(148,163,184,.045);overflow:hidden}
.tree-toggle{width:100%;display:flex;align-items:center;justify-content:space-between;gap:10px;padding:11px 12px;color:var(--text);background:transparent;border:0;font-weight:900;letter-spacing:-.01em;text-align:left}
.tree-toggle:hover{background:rgba(148,163,184,.09)}
.chev{transition:transform .15s ease;color:var(--muted);font-size:13px}
.tree-section.collapsed .chev{transform:rotate(-90deg)}
.tree-children{display:grid;gap:3px;padding:0 8px 9px}
.tree-section.collapsed .tree-children{display:none}
.tree-link{display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:34px;padding:8px 9px;border-radius:11px;color:var(--muted);text-decoration:none;font-size:13px;border:1px solid transparent}
.tree-link:hover{color:var(--text);background:rgba(148,163,184,.08)}
.tree-link.active{color:white;background:linear-gradient(135deg,var(--purple),var(--blue));border-color:transparent}
.tree-link.child{padding-left:18px;font-size:12px}
.tree-link.grandchild{padding-left:30px;font-size:12px}
.tree-link .mini{font-size:10px;color:inherit;opacity:.75;border:1px solid rgba(255,255,255,.16);border-radius:999px;padding:2px 6px}
.sidebar-note{padding:10px 12px;color:var(--muted);font-size:12px;line-height:1.45;border:1px solid var(--line);border-radius:14px;background:rgba(148,163,184,.04)}
.anchor-target{scroll-margin-top:18px}
@media(max-width:1040px){.nav-tree{grid-template-columns:1fr}.sidebar{height:auto}.tree-section.collapsed .tree-children{display:none}}


/* v10 deeper hierarchy */
.tree-subtoggle{
  width:100%;
  display:flex;
  align-items:center;
  justify-content:space-between;
  gap:8px;
  min-height:31px;
  margin-top:4px;
  padding:7px 9px 7px 18px;
  border-radius:11px;
  border:1px solid transparent;
  color:var(--text);
  background:rgba(148,163,184,.055);
  font-size:12px;
  font-weight:850;
  text-align:left;
}
.tree-subtoggle:hover{background:rgba(148,163,184,.11)}
.tree-subtoggle.subcollapsed .chev{transform:rotate(-90deg)}
.tree-subchildren{display:grid;gap:2px;margin:2px 0 5px;padding-left:8px}
.tree-subchildren.collapsed-sub{display:none}
.tree-link.leaf{padding-left:32px;font-size:11.5px;min-height:30px}
.tree-empty{
  display:block;
  margin:3px 8px 6px 32px;
  padding:7px 9px;
  border-radius:10px;
  color:var(--muted);
  border:1px dashed var(--line);
  font-size:11.5px;
}


/* v11 sidebar visibility and complete panel-list fix */
.shell{grid-template-columns:minmax(430px,34vw) minmax(0,1fr)}
.main{min-width:0}
.sidebar{overflow-y:auto;overflow-x:visible;min-width:430px;z-index:5}
.tree-section{overflow:visible}
.tree-toggle,.tree-subtoggle,.tree-link{white-space:normal;line-height:1.35;align-items:flex-start}
.tree-toggle span:first-child,.tree-subtoggle span:first-child,.tree-link{min-width:0;word-break:normal;overflow-wrap:anywhere}
.tree-link{justify-content:flex-start;gap:8px}
.tree-link .mini{margin-left:auto;flex:0 0 auto;max-width:150px;white-space:normal;text-align:right;overflow-wrap:anywhere}
.tree-link.leaf{padding-left:30px}
.tree-children,.tree-subchildren{min-width:0}
.tree-controls{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:-6px 0 2px}
.tree-controls button{min-height:34px;border-radius:11px;border:1px solid var(--line);background:rgba(148,163,184,.075);color:var(--text);font-size:12px;font-weight:850}
.tree-controls button:hover{background:rgba(148,163,184,.14)}
.panel-leaf{font-weight:850;color:var(--text)}
@media(max-width:1040px){.shell{grid-template-columns:1fr}.sidebar{position:relative;min-width:0;height:auto}.main{min-width:0}}


/* v14 programming tree */
.programming-card{margin-top:18px}
.program-entry,.program-node{
  border:1px solid var(--line);
  border-radius:16px;
  background:rgba(148,163,184,.055);
  margin:10px 0;
  overflow:hidden;
}
.program-entry>summary,.program-node>summary{
  cursor:pointer;
  display:flex;
  align-items:center;
  gap:10px;
  padding:12px 14px;
  color:var(--text);
  list-style:none;
}
.program-entry>summary::-webkit-details-marker,.program-node>summary::-webkit-details-marker{display:none}
.program-entry>summary:before,.program-node>summary:before{content:'▾';color:var(--muted);transition:transform .15s ease}
.program-entry:not([open])>summary:before,.program-node:not([open])>summary:before{transform:rotate(-90deg)}
.program-entry>summary span,.program-node>summary span{min-width:0;overflow-wrap:anywhere}
.program-entry>summary span:last-child{color:var(--muted);font-size:12px;line-height:1.4}
.program-node summary em{
  margin-left:auto;
  color:var(--muted);
  font-size:11px;
  font-style:normal;
  white-space:nowrap;
}
.program-children{padding:0 12px 10px 18px}
.program-leaf{
  display:flex;
  align-items:flex-start;
  gap:10px;
  padding:9px 10px;
  margin:4px 0;
  border-radius:12px;
  border:1px solid rgba(148,163,184,.12);
  background:rgba(2,6,23,.14);
  color:var(--muted);
  overflow-wrap:anywhere;
}
.program-leaf small{display:block;color:var(--yellow);font-size:11px;margin-left:auto;max-width:280px}
.program-code{
  flex:0 0 auto;
  min-width:45px;
  text-align:center;
  padding:2px 7px;
  border-radius:999px;
  color:var(--text);
  background:rgba(6,182,212,.14);
  border:1px solid rgba(6,182,212,.25);
  font-size:12px;
  font-weight:900;
}
.program-node.level-2{margin-left:8px}
.program-node.level-3{margin-left:16px}
.program-node.level-4{margin-left:24px}
@media(max-width:680px){.program-entry>summary,.program-node>summary,.program-leaf{align-items:flex-start}.program-node summary em,.program-leaf small{margin-left:0}}


/* v15 right-side document viewer */
#view-document{max-width:1200px}
.document-title-row{align-items:flex-start}
.document-toolbar{justify-content:flex-end}
.document-card{padding:22px;min-height:520px}
.document-meta-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:10px;margin-bottom:14px}
.document-meta-grid div{border:1px solid var(--line);background:rgba(148,163,184,.06);border-radius:14px;padding:12px}
.document-meta-grid strong{display:block;color:var(--text);font-size:18px}
.document-meta-grid span{display:block;color:var(--muted);font-size:12px;margin-top:3px}
.word-outline{max-width:980px;margin:0 auto;padding:8px 0 20px}
.word-outline h2{font-size:26px;margin:14px 0 4px;letter-spacing:-.03em}
.word-outline .program-entry,.word-outline .program-node{background:rgba(255,255,255,.03)}
.word-outline .program-node.level-1{margin-top:14px}
.word-outline .program-node.level-2{margin-left:18px}
.word-outline .program-node.level-3{margin-left:36px}
.word-outline .program-node.level-4{margin-left:54px}
.word-outline .program-leaf.level-2{margin-left:18px}
.word-outline .program-leaf.level-3{margin-left:36px}
.word-outline .program-leaf.level-4{margin-left:54px}
.tree-link[data-doc-type="programming"]:before{content:'📄';font-size:12px;margin-right:4px}
@media(max-width:900px){.word-outline .program-node.level-2,.word-outline .program-node.level-3,.word-outline .program-node.level-4,.word-outline .program-leaf.level-2,.word-outline .program-leaf.level-3,.word-outline .program-leaf.level-4{margin-left:0}.document-card{padding:14px}}



/* v16 programming outline refinement */
.programming-card .toolbar{flex-wrap:wrap}
.program-document{
