  font-size:12px !important;
  font-weight:900;
  line-height:18px;
}
.program-line small{
  color:var(--yellow);
  font-size:11px;
  max-width:280px;
}
.program-node.level-1,.program-node.level-2,.program-node.level-3,.program-node.level-4{margin-left:0 !important}
