.neo-hs2lcd-keypad{
  --hs2lcd-lcd-color:#00B3FF;
  --hs2lcd-lcd-rgb:32,183,236;
  --hs2lcd-key-color:#C6E3F5;
  --hs2lcd-key-rgb:32,183,236;
  --hs2lcd-bar-color:#00B3FF;
  --hs2lcd-bar-rgb:32,183,236;
  --hs2lcd-status-bg:#D2D7DB;
  --hs2lcd-lcd-intensity:1;
  --hs2lcd-key-intensity:1;
  --hs2lcd-bar-intensity:1;
  width:min(980px,100%);
  min-width:640px;
  aspect-ratio:2048/1503;
  position:relative;
  isolation:isolate;
  filter:drop-shadow(0 24px 28px rgba(0,0,0,.34));
  user-select:none;
}
.hs2lcd-chassis{
  position:absolute;inset:0;width:100%;height:100%;display:block;
  object-fit:contain;pointer-events:none;border-radius:4.5%;
}
.hs2lcd-screen{
  position:absolute;
  left:20.56%;top:10.31%;width:59.03%;height:20.23%;
  box-sizing:border-box;
  border-radius:2.4%/10.5%;
  overflow:hidden;
  isolation:isolate;
  background:linear-gradient(180deg,#748188 0%,#68757B 54%,#5E6A70 100%);
  transition:box-shadow .16s ease;
  box-shadow:inset 0 0 22px rgba(0,0,0,.40),inset 0 2px 2px rgba(255,255,255,.10);
}
.hs2lcd-screen:before{
  content:"";position:absolute;inset:0;z-index:0;pointer-events:none;
  background:var(--hs2lcd-lcd-color);
  opacity:calc(.08 + (var(--hs2lcd-lcd-intensity) * .84));
  mix-blend-mode:color;
  transition:opacity .16s ease;
}
.neo-hs2lcd-keypad.lcd-backlight-off .hs2lcd-screen:before,
.neo-hs2lcd-keypad.keypad-power-off .hs2lcd-screen:before{opacity:0}
.neo-hs2lcd-keypad:not(.lcd-backlight-off):not(.keypad-power-off) .hs2lcd-screen{
  box-shadow:inset 0 0 22px rgba(0,42,70,.38),inset 0 2px 2px rgba(255,255,255,.18),0 0 calc(3px + 5px * var(--hs2lcd-lcd-intensity)) rgba(var(--hs2lcd-lcd-rgb),calc(.12 + .22 * var(--hs2lcd-lcd-intensity)));
}
.hs2lcd-lcd-canvas{position:relative;z-index:1;display:block;width:100%;height:100%;image-rendering:auto;filter:contrast(1.04);opacity:1;will-change:opacity}
.hs2lcd-screen-slot{
  position:absolute;left:35.30%;top:33.80%;width:29.60%;height:1.86%;
  border-radius:999px;overflow:hidden;isolation:isolate;
  background:linear-gradient(180deg,#aeb8bd 0%,#7f8b91 48%,#66737a 100%);
  border:1px solid rgba(72,84,91,.88);
  box-shadow:inset 0 1px 2px rgba(255,255,255,.30),inset 0 -1px 2px rgba(0,0,0,.32);
  transition:border-color .15s,box-shadow .15s;
}
.hs2lcd-screen-slot:after{
  content:"";position:absolute;inset:0;pointer-events:none;
  background:var(--hs2lcd-bar-color);
  opacity:0;
  mix-blend-mode:color;
  transition:opacity .15s ease;
}
.hs2lcd-screen-slot.active:after{opacity:calc(.08 + (var(--hs2lcd-bar-intensity) * .88))}
.hs2lcd-screen-slot.active{
  border-color:rgba(72,84,91,.88);
  box-shadow:0 0 calc(2px + 8px * var(--hs2lcd-bar-intensity)) rgba(var(--hs2lcd-bar-rgb),calc(.12 + .48 * var(--hs2lcd-bar-intensity))),inset 0 1px 2px rgba(255,255,255,.30),inset 0 -1px 2px rgba(0,0,0,.28);
}
.neo-hs2lcd-keypad.keypad-power-off .hs2lcd-screen-slot:after{opacity:0}
.neo-hs2lcd-keypad.keypad-power-off .hs2lcd-screen-slot{box-shadow:inset 0 1px 2px rgba(255,255,255,.30),inset 0 -1px 2px rgba(0,0,0,.32)}
.hs2lcd-status-cover{
  position:absolute;left:80.72%;top:10.46%;width:5.15%;height:20.25%;
  border-radius:0;
  display:grid;place-items:center;
  background:linear-gradient(180deg,#D7DCE2 0%,#D2D8DE 38%,#D2D8DD 72%,#D4D9DF 100%);
  box-shadow:none;
}
.hs2lcd-status-column{width:100%;height:100%;display:grid;grid-template-rows:repeat(4,1fr);align-items:center;justify-items:center}
.hs2lcd-status-lamp{
  width:62%;height:62%;display:grid;place-items:center;
  color:#8F999E;opacity:.10;
  transition:opacity .15s,filter .15s,color .15s;
}
.hs2lcd-status-lamp.active{opacity:1}
.hs2lcd-led-svg{width:100%;height:100%;overflow:visible;fill:none;stroke:currentColor;stroke-width:3.25;stroke-linecap:round;stroke-linejoin:round}
.hs2lcd-led-svg .fill{fill:currentColor;stroke:none}
.hs2lcd-led-svg .cut{fill:var(--hs2lcd-status-bg);stroke:none}
.hs2lcd-led-svg .cut-stroke{stroke:var(--hs2lcd-status-bg);stroke-width:2.3}
.hs2lcd-status-lamp[data-status-lamp=ready].active{color:#159447;filter:drop-shadow(0 0 5px rgba(21,148,71,.58))}
.hs2lcd-status-lamp[data-status-lamp=armed].active{color:#d92437;filter:drop-shadow(0 0 5px rgba(217,36,55,.62))}
.hs2lcd-status-lamp[data-status-lamp=trouble].active{color:#e0a500;filter:drop-shadow(0 0 5px rgba(224,165,0,.64))}
.hs2lcd-status-lamp[data-status-lamp=ac].active{color:#159447;filter:drop-shadow(0 0 5px rgba(21,148,71,.58))}
.hs2lcd-hotspot-layer{position:absolute;inset:0}
.hs2lcd-key{
  position:absolute;border:0;background:transparent;color:transparent;padding:0;margin:0;
  border-radius:999px;cursor:pointer;isolation:auto;overflow:hidden;
  transition:box-shadow .08s,filter .08s;
}
/* First neutralize the blue baked into the photo while preserving its
   luminance, labels, edges and surface detail. */
.hs2lcd-key:before{
  content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none;
  background:#C9CED1;opacity:1;mix-blend-mode:color;
}
/* The selected backlight hue is a fixed transparent overlay. Brightness
   changes only this overlay's opacity, never the hue itself. */
.hs2lcd-key:after{
  content:"";position:absolute;inset:0;border-radius:inherit;pointer-events:none;
  background:var(--hs2lcd-key-color);mix-blend-mode:color;
  opacity:calc(.06 + (var(--hs2lcd-key-intensity) * .90));
  transition:opacity .16s ease;
}
.neo-hs2lcd-keypad.key-backlight-off .hs2lcd-key:after,
.neo-hs2lcd-keypad.keypad-power-off .hs2lcd-key:after{opacity:0}
.hs2lcd-key:hover{box-shadow:inset 0 0 0 2px rgba(14,165,233,.18)}
/* Do not translate or blank the transparent hotspot: the photographed key
   beneath it cannot move. A subtle inset shade communicates the press. */
.hs2lcd-key:active{background:rgba(0,0,0,.08);box-shadow:inset 0 3px 5px rgba(0,0,0,.22)}
.hs2lcd-key:active:after{filter:brightness(.84)}
.hs2lcd-key:focus-visible{outline:3px solid #0ea5e9;outline-offset:2px}

