/* v98: workspace-wide search and collapsed-by-default navigation */
.workspace-search-wrap{display:flex;align-items:center;gap:10px;flex:1;min-width:0}
.workspace-search-wrap .search{min-width:260px}
.search-results-toggle{white-space:nowrap}
.search-results-toggle.active{color:#111827;background:var(--yellow);border-color:transparent;font-weight:900}
.workspace-search-status{min-width:130px;color:var(--muted);font-size:12px;white-space:nowrap}
mark.dsc-search-hit{padding:0 .12em;border-radius:4px;background:var(--yellow);color:#111827;font-weight:900}
.dsc-search-match>.program-row,.program-leaf-row.dsc-search-match,.tree-link.dsc-search-match,.tree-subtoggle.dsc-search-match{background:rgba(251,191,36,.14)!important;box-shadow:inset 3px 0 0 var(--yellow)}
.dsc-search-hidden{display:none!important}
.program-field-info.dsc-search-detail-hidden{display:none!important}
@media(max-width:900px){.workspace-search-wrap{flex-wrap:wrap}.workspace-search-status{min-width:0}.search-results-toggle{flex:0 0 auto}}


/* v99: fast lazy programming renderer and precise section search */
.tree-program-section-link{padding-left:42px!important}
.tree-program-document-link{font-weight:800}
.tree-subtoggle.dsc-search-has-match:not(.dsc-search-match),.tree-section.dsc-search-has-match>.tree-toggle{box-shadow:inset 2px 0 0 rgba(251,191,36,.5)}
.dsc-search-path>.program-row{box-shadow:inset 2px 0 0 rgba(251,191,36,.45)}
.program-fold-lazy-children{display:block}

/* v100: immediate frame-scheduled search with visible collapsed-tree result indicators */
.dsc-search-match>.program-row,
.program-leaf-row.dsc-search-match,
.tree-link.dsc-search-match,
.tree-subtoggle.dsc-search-match,
.tree-toggle.dsc-search-match{
  background:rgba(251,191,36,.16)!important;
  box-shadow:inset 4px 0 0 var(--yellow);
  border-color:rgba(251,191,36,.32)!important;
  color:var(--text)
}
.tree-subtoggle.dsc-search-has-match:not(.dsc-search-match),
.tree-toggle.dsc-search-has-match:not(.dsc-search-match){
  background:rgba(251,191,36,.105)!important;
  box-shadow:inset 4px 0 0 rgba(251,191,36,.82);
  border-color:rgba(251,191,36,.24)!important;
  color:var(--text)
}
.tree-section.dsc-search-has-match{border-color:rgba(251,191,36,.30)}
.tree-toggle[data-search-count]::after,
.tree-subtoggle[data-search-count]::after{
  content:attr(data-search-count);
  display:inline-grid;
  place-items:center;
  min-width:24px;
  height:21px;
  margin-left:auto;
  padding:0 7px;
  border-radius:999px;
  background:rgba(251,191,36,.18);
  border:1px solid rgba(251,191,36,.34);
  color:var(--yellow);
  font-size:10px;
  font-weight:900;
  line-height:1;
  order:1;
  flex:0 0 auto
}
.tree-toggle>.chev,.tree-subtoggle>.chev{order:2;flex:0 0 auto}
.tree-toggle>span:first-child,.tree-subtoggle>span:first-child{order:0}


/* v101: complete lazy programming navigation and deep indexed search */
.tree-program-node{min-width:0}
.tree-program-node-row{display:flex;align-items:stretch;min-width:0}
.tree-program-node-toggle{
  width:28px;
  min-width:28px;
  margin:2px 0 2px calc((var(--tree-depth,1) - 1) * 12px);
  padding:0;
  border:0;
  border-radius:8px;
  background:transparent;
  color:var(--muted);
  display:grid;
  place-items:center
}
.tree-program-node-toggle:hover{background:rgba(148,163,184,.12);color:var(--text)}
.tree-program-node-toggle.subcollapsed .chev{transform:rotate(-90deg)}
.tree-program-node-link{flex:1;min-width:0;padding-left:8px!important}
.tree-program-node-leaf>.tree-program-node-link{padding-left:calc(36px + (var(--tree-depth,1) - 1) * 12px)!important}
.tree-program-node-children{display:grid;gap:2px;min-width:0}
.tree-program-node-children.collapsed-sub{display:none}
.tree-program-node.dsc-search-has-match>.tree-program-node-row>.tree-program-node-link:not(.dsc-search-match),
.tree-program-node.dsc-search-has-match>.tree-program-node-link:not(.dsc-search-match){
  background:rgba(251,191,36,.075)!important;
  box-shadow:inset 2px 0 0 rgba(251,191,36,.58)
}
.tree-program-node-toggle.dsc-search-has-match{color:var(--yellow);background:rgba(251,191,36,.11)}
.tree-program-node-link[data-search-count]::after,
.tree-program-document-link[data-search-count]::after{
  content:attr(data-search-count);
  display:inline-grid;
  place-items:center;
  min-width:24px;
  height:21px;
  margin-left:auto;
  padding:0 7px;
  border-radius:999px;
  background:rgba(251,191,36,.18);
  border:1px solid rgba(251,191,36,.34);
  color:var(--yellow);
  font-size:10px;
  font-weight:900;
  line-height:1;
  flex:0 0 auto
}
.tree-program-node-toggle[data-search-count]::after{
  content:'';
  width:7px;
  height:7px;
  border-radius:999px;
  background:var(--yellow);
  box-shadow:0 0 0 3px rgba(251,191,36,.16)
}
.program-row[data-search-count]::after{
  content:attr(data-search-count) ' below';
  margin-left:auto;
  padding:3px 8px;
  border-radius:999px;
  background:rgba(251,191,36,.13);
  border:1px solid rgba(251,191,36,.26);
  color:var(--yellow);
  font-size:10px;
  font-weight:900;
  white-space:nowrap
}

/* v103: resizable split, full-width hierarchy, document-opening entry rows, and strict right-side result filtering */
.shell{
  --sidebar-width:430px;
  grid-template-columns:var(--sidebar-width) 8px minmax(0,1fr);
  align-items:stretch
}
.sidebar{
  min-width:0;
  width:auto;
  overflow-y:auto;
  overflow-x:hidden;
  border-right:0;
  scrollbar-gutter:stable
}
.sidebar-resizer{
  position:sticky;
  top:0;
  z-index:20;
  width:8px;
  height:100vh;
  cursor:col-resize;
  touch-action:none;
  background:linear-gradient(90deg,transparent,rgba(148,163,184,.24),transparent);
  border-left:1px solid rgba(148,163,184,.08);
  border-right:1px solid rgba(148,163,184,.08)
}
.sidebar-resizer::after{
  content:'';
  position:absolute;
  top:50%;
  left:2px;
  width:3px;
  height:58px;
  transform:translateY(-50%);
  border-radius:999px;
  background:rgba(148,163,184,.42);
  transition:background .12s ease,box-shadow .12s ease
}
.sidebar-resizer:hover::after,
.sidebar-resizer:focus-visible::after,
body.is-resizing-sidebar .sidebar-resizer::after{
  background:var(--blue);
  box-shadow:0 0 0 4px rgba(6,182,212,.14)
}
.sidebar-resizer:focus-visible{outline:2px solid var(--blue);outline-offset:-2px}
body.is-resizing-sidebar{cursor:col-resize;user-select:none}
body.is-resizing-sidebar iframe{pointer-events:none}

/* Each navigation row fills the current sidebar width. Depth is internal padding, never a wider canvas. */
.nav-tree,
.nav-tree .tree-controls,
.nav-tree .sidebar-note,
.nav-tree .tree-section,
.nav-tree .tree-children,
.nav-tree .tree-subchildren,
.nav-tree .tree-program-node-children{
  width:100%;
  min-width:0;
  max-width:100%
}
.nav-tree{padding-right:0}
.nav-tree .tree-toggle,
.nav-tree .tree-subtoggle,
.nav-tree .tree-link{
  box-sizing:border-box;
  width:100%;
  max-width:100%;
  min-width:0;
  white-space:normal;
  overflow-wrap:anywhere;
  word-break:normal
}
.tree-toggle>span:first-child,
.tree-subtoggle>span:first-child,
.tree-link>.tree-label{
  flex:1 1 auto;
  min-width:0;
  overflow-wrap:anywhere
}
.tree-link>.mini{
  flex:0 0 auto;
  max-width:110px;
  margin-left:auto;
  white-space:normal;
  overflow-wrap:anywhere;
  text-align:right
}
.tree-children{padding:0 0 9px 8px}
.tree-subchildren{
  position:relative;
  box-sizing:border-box;
  margin:2px 0 5px;
  padding-left:16px;
  border-left:1px solid rgba(56,189,248,.34)
}
.tree-subtoggle{padding-left:18px}
.tree-subtoggle[data-doc-type="programming"]{cursor:pointer}
.tree-subtoggle[data-doc-type="programming"].active{
  color:white;
  background:linear-gradient(135deg,var(--purple),var(--blue));
  border-color:transparent;
  box-shadow:none
}
.tree-subtoggle[data-doc-type="programming"].active .chev{color:rgba(255,255,255,.86)}

.tree-program-node,
.tree-program-node-row,
.tree-program-node-children{
  position:relative;
  box-sizing:border-box;
  width:100%;
  min-width:0;
  max-width:100%
}
.tree-program-node-row{
  display:flex;
  align-items:stretch;
  padding-left:calc((var(--tree-depth,1) - 1) * 18px)
}
.tree-program-node-row::before{
  content:'';
  position:absolute;
  left:calc((var(--tree-depth,1) - 1) * 18px + 1px);
  top:50%;
  width:14px;
  border-top:1px solid rgba(56,189,248,.52);
  pointer-events:none
}
.tree-program-node-toggle{
  margin-left:0;
  flex:0 0 28px
}
.tree-program-node-link{
  flex:1 1 auto;
  width:auto;
  min-width:0;
  max-width:100%;
  padding-left:8px!important
}
.tree-program-node-leaf>.tree-program-node-link{
  position:relative;
  box-sizing:border-box;
  width:100%;
  min-width:0;
  max-width:100%;
  margin-left:0;
  padding-left:calc(36px + (var(--tree-depth,1) - 1) * 18px)!important
}
.tree-program-node-leaf>.tree-program-node-link::before{
  content:'';
  position:absolute;
  left:calc((var(--tree-depth,1) - 1) * 18px + 1px);
  top:50%;
  width:22px;
  border-top:1px solid rgba(56,189,248,.52);
  pointer-events:none
}
.tree-program-node-children:not(.collapsed-sub)::before{
  content:'';
  position:absolute;
  top:0;
  bottom:8px;
  left:calc((var(--tree-depth,1) - 1) * 18px + 14px);
  border-left:1px solid rgba(56,189,248,.28);
  pointer-events:none
}
.tree-toggle[data-search-count]::after,
.tree-subtoggle[data-search-count]::after,
.tree-program-node-link[data-search-count]::after,
.tree-program-document-link[data-search-count]::after{flex:0 0 auto}

/* Only-results filters the active right pane too; ancestor paths remain for context. */
.workspace-search-empty{
  margin:0 0 18px;
  padding:14px 16px;
  border:1px solid rgba(251,191,36,.34);
  border-radius:16px;
  background:rgba(251,191,36,.10);
  color:var(--text);
  font-weight:750
}
.view.dsc-search-only-results .document-meta-grid.dsc-search-hidden,
.view.dsc-search-only-results .source-note.dsc-search-hidden,
.view.dsc-search-only-results .warning.dsc-search-hidden,
.view.dsc-search-only-results .word-outline>h2.dsc-search-hidden,
.view.dsc-search-only-results .word-outline>p.dsc-search-hidden,
.view.dsc-search-only-results>.section-title.dsc-search-hidden{
  display:none!important
}

@media(max-width:1040px){
  .shell{grid-template-columns:1fr}
  .sidebar-resizer{display:none}
  .sidebar{position:relative;width:auto;min-width:0;height:auto;border-bottom:1px solid var(--line);overflow-x:hidden}
}

/* v104: search indexes visible programming content only; internal relationship metadata is excluded */

/* v105: exact-only right-pane filtering and identical direct-result highlighting */
.dsc-search-match > .program-row,
.program-leaf-row.dsc-search-match{
  background:rgba(251,191,36,.16)!important;
  box-shadow:inset 4px 0 0 var(--yellow)!important;
  border-color:rgba(251,191,36,.32)!important;
  color:var(--text)!important
}

/* A path-only programming parent is never shown as a result on the right.
   When already open, it may act as a zero-chrome container for exact children. */
.view.dsc-search-only-results .program-block.dsc-search-result-container > .program-row,
.view.dsc-search-only-results .program-block.dsc-search-result-container > .program-field-info,
.view.dsc-search-only-results .program-fold.dsc-search-result-container > .program-row,
.view.dsc-search-only-results .program-fold.dsc-search-result-container > .program-field-info,
.view.dsc-search-only-results .program-fold.dsc-search-result-container > .program-fold-expanded > .program-collapse-range{
  display:none!important
}
.view.dsc-search-only-results .program-block.dsc-search-result-container,
.view.dsc-search-only-results .program-fold.dsc-search-result-container{
  margin:0!important;
  padding:0!important;
  border:0!important;
  background:transparent!important;
  box-shadow:none!important
}

/* Search visibility must outrank the legacy programming layout's !important display rules. */
body .dsc-search-hidden.dsc-search-hidden{
  display:none!important
}

/* v106: right-pane filtering uses the same direct-or-descendant result set as the left tree. */
.view.dsc-search-only-results .dsc-search-path > .program-row,
.view.dsc-search-only-results .program-leaf-row.dsc-search-path{
  background:rgba(251,191,36,.075)!important;
  box-shadow:inset 2px 0 0 rgba(251,191,36,.58)!important;
  color:var(--text)!important
}


/* v107: right-pane result rows use the same complete amber treatment as left navigation results. */
#documentBody .program-block.dsc-search-path > .program-row,
#documentBody .program-fold.dsc-search-path > .program-row,
#documentBody .program-leaf-row.dsc-search-path,
#documentBody .program-block.dsc-search-match > .program-row,
#documentBody .program-fold.dsc-search-match > .program-row,
#documentBody .program-leaf-row.dsc-search-match{
  background:rgba(251,191,36,.14)!important;
  box-shadow:inset 4px 0 0 var(--yellow)!important;
  border:1px solid rgba(251,191,36,.34)!important;
  border-radius:11px!important;
  box-sizing:border-box!important;
  color:var(--text)!important;
}
#documentBody .program-block.dsc-search-path > .program-row:hover,
#documentBody .program-fold.dsc-search-path > .program-row:hover,
#documentBody .program-leaf-row.dsc-search-path:hover,
#documentBody .program-block.dsc-search-match > .program-row:hover,
#documentBody .program-fold.dsc-search-match > .program-row:hover,
#documentBody .program-leaf-row.dsc-search-match:hover{
  background:rgba(251,191,36,.18)!important;
}


/* v108: searchable lazy references and collision-safe allowed-values cells. */
.program-allowed-values-table td{
  white-space:normal !important;
  overflow-wrap:anywhere !important;
  word-break:normal !important;
  vertical-align:top !important;
}
.program-allowed-values-table .program-option-code,
.program-allowed-values-table .program-option-separator,
.program-allowed-values-table .program-option-label{
  white-space:normal !important;
}

/* v109: compact zone-rule field information and clearer right-side hierarchy guides. */
.program-zone-rule-lines{
  display:grid !important;
  grid-template-columns:minmax(0,1fr) !important;
  gap:4px !important;
  width:100% !important;
  min-width:0 !important;
  margin:0 !important;
  padding:0 !important;
  line-height:1.42 !important;
}
.program-zone-rule-line{
  display:block !important;
  min-width:0 !important;
  margin:0 !important;
  padding:0 !important;
  color:#cbd5e1 !important;
  font-size:12px !important;
  line-height:1.42 !important;
  overflow-wrap:anywhere !important;
}
.program-zone-rule-line.program-zone-rule-heading{
  margin-top:5px !important;
  color:#e2e8f0 !important;
  font-weight:900 !important;
}
.program-zone-rule-line.program-zone-rule-heading:first-child{
  margin-top:0 !important;
}
.program-field-row.eol-behavior .program-field-rich,
.program-field-row.resistor-wiring .program-field-rich{
  display:block !important;
  gap:0 !important;
}
.program-zone-type-eol .program-zone-rule-lines,
.program-zone-type-resistor .program-zone-rule-lines{
  gap:3px !important;
}
html[data-theme="light"] .program-zone-rule-line{
  color:#334155 !important;
}
html[data-theme="light"] .program-zone-rule-line.program-zone-rule-heading{
  color:#0f172a !important;
}

/* One branch line per open parent, aligned to the exact depth of its children. */
.program-block.is-open > .program-children::before,
.program-fold.is-open > .program-fold-expanded::before{
  left:calc((var(--depth,0) * var(--indent-step,28px)) + 10px) !important;
  top:-2px !important;
  bottom:20px !important;
  width:1px !important;
  border-radius:0 !important;
  background:rgba(56,189,248,.48) !important;
  box-shadow:none !important;
}
/* Child rows use a clean elbow connected to their parent's branch line. */
.program-guide{
  left:-18px !important;
  top:0 !important;
  bottom:0 !important;
  width:30px !important;
}
.program-guide .guide-v{
  display:none !important;
}
.program-guide .guide-h{
  left:0 !important;
  top:50% !important;
  width:28px !important;
  height:1px !important;
  border-radius:0 !important;
  background:rgba(56,189,248,.66) !important;
  box-shadow:none !important;
}
.program-row:hover .program-guide .guide-h,
.program-block.dsc-search-match > .program-row .program-guide .guide-h,
.program-block.dsc-search-path > .program-row .program-guide .guide-h,
.program-fold.dsc-search-match > .program-row .program-guide .guide-h,
.program-fold.dsc-search-path > .program-row .program-guide .guide-h,
.program-leaf-row.dsc-search-match .program-guide .guide-h,
.program-leaf-row.dsc-search-path .program-guide .guide-h{
  background:rgba(125,211,252,.96) !important;
}
.program-collapse-range::before{
  left:-18px !important;
  width:18px !important;
  height:1px !important;
  border-radius:0 !important;
  background:rgba(56,189,248,.66) !important;
  box-shadow:none !important;
}
@media(max-width:760px){
  .program-block.is-open > .program-children::before,
  .program-fold.is-open > .program-fold-expanded::before{
    left:calc((var(--depth,0) * var(--indent-step,18px)) + 7px) !important;
  }
  .program-guide{
    left:-11px !important;
    width:20px !important;
  }
  .program-guide .guide-h{
    left:0 !important;
    width:18px !important;
  }
  .program-collapse-range::before{
    left:-11px !important;
    width:11px !important;
  }
}

/* v110 panel-family navigation architecture */
.tree-scope-note{
  display:block;
  margin:4px 8px 7px 18px;
  padding:7px 9px;
  border-left:2px solid rgba(6,182,212,.6);
  color:var(--muted);
  font-size:11px;
  line-height:1.45;
}
.tree-subtoggle[data-tree-role="family-category"]{
  font-size:12.5px;
  font-weight:900;
}
.tree-subtoggle[data-tree-role="model"]{
  background:rgba(6,182,212,.055);
  border-color:rgba(6,182,212,.12);
}
.tree-subtoggle[data-tree-role="model-programming"]{
  background:rgba(124,58,237,.055);
  font-size:11.75px;
}
.tree-version-unlinked{border-style:solid;opacity:.82}


/* v111 simplified family workspace */
html{scroll-behavior:auto}
.workspace-home{min-height:calc(100vh - 120px)}
.workspace-empty-state{min-height:calc(100vh - 150px);display:grid;place-items:center;color:var(--muted);text-align:center;padding:30px}
.workspace-empty-state strong{font-size:16px;font-weight:750}
.compact-view-heading{margin-bottom:12px}
.compact-view-heading h1{font-size:clamp(28px,4vw,44px)}
.document-title-row h1{font-size:clamp(30px,4vw,48px)}
#documentSubtitle:empty{display:none}
.programming-document-clean{max-width:none;margin:0;padding:0 0 20px}
.document-card{padding:14px}
.tree-toggle,.tree-subtoggle{justify-content:flex-start!important;align-items:center!important}
.tree-toggle>.chev,.tree-subtoggle>.chev{order:0!important;flex:0 0 18px!important;margin:0!important}
.tree-toggle>.tree-label,.tree-subtoggle>.tree-label{order:1!important;flex:1 1 auto!important;min-width:0}
.tree-toggle[data-search-count]::after,.tree-subtoggle[data-search-count]::after{order:2!important}
.tree-link.leaf{padding-left:30px}
.tree-action-branch{width:100%;min-width:0}
.tree-action-row{display:flex;align-items:stretch;width:100%;min-width:0}
.tree-action-toggle{flex:0 0 30px;width:30px;min-width:30px;margin:2px 0;padding:0;border:0;border-radius:9px;background:transparent;color:var(--muted);display:grid;place-items:center}
.tree-action-toggle:hover{background:rgba(148,163,184,.12);color:var(--text)}
.tree-action-toggle .chev{transition:transform .15s ease}
.tree-action-toggle.subcollapsed .chev{transform:rotate(-90deg)}
.tree-action-row>.tree-link{flex:1 1 auto;width:auto;min-width:0;padding-left:7px!important}
.tree-model-entry>.tree-subchildren,.tree-program-entry>.tree-subchildren{margin-left:14px}
.nav-tree .tree-link[data-inventory-kind],.nav-tree .tree-link[data-comparison-key],.nav-tree .tree-link[data-placeholder-title],.nav-tree .tree-link[data-virtual-keypad-target]{padding-left:30px;font-weight:750}
.workspace-table-view{height:calc(100vh - 92px);min-height:560px;overflow:hidden}
.workspace-data-card{height:calc(100% - 115px);min-height:0;padding:0;overflow:hidden}
.workspace-data-card>.table-scroll{height:100%;max-height:none;border:0;border-radius:var(--radius);overflow:auto}
.workspace-data-card .compare-table{min-width:760px}
.workspace-data-card .compare-table thead th{position:sticky;top:0;z-index:4;background:#111b2f;box-shadow:0 1px 0 var(--line2)}
html[data-theme=light] .workspace-data-card .compare-table thead th{background:#f8fafc}
.comparison-model-controls{display:flex;flex-wrap:wrap;gap:8px;margin:0 0 12px}
.comparison-model-toggle{min-height:36px;padding:0 13px;border-radius:12px;border:1px solid var(--line);background:var(--panel2);color:var(--muted);font-weight:850}
