/* v188 — PowerSeries NEO tutorials/useful information/tools and keypad references. */
.workspace-reference-view{height:calc(100vh - 92px);height:calc(100dvh - 92px);min-height:560px;overflow:hidden}
.reference-title-row{margin-bottom:14px}
.reference-title-row h1{margin-bottom:6px}
.reference-content-card{height:calc(100% - 106px);min-height:0;padding:0;overflow-x:hidden;overflow-y:auto;scrollbar-gutter:stable;overscroll-behavior:contain}
.reference-intro{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:16px 18px;border-bottom:1px solid var(--line)}
.reference-intro>p{margin:0;color:var(--muted);font-size:13px;line-height:1.55;max-width:880px}
.reference-example,.reference-count{display:flex;align-items:center;gap:9px;flex:0 0 auto;padding:9px 12px;border:1px solid var(--line);border-radius:13px;background:rgba(6,182,212,.08)}
.reference-example strong,.reference-count strong{color:var(--text)}
.reference-example span,.reference-count span{color:var(--muted);font-size:12px}
.reference-table-scroll{width:100%;overflow:visible;border:0;border-radius:0;background:transparent}
.reference-table{width:100%;min-width:0;border-collapse:collapse;table-layout:fixed}
.reference-table th,.reference-table td{padding:7px 9px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);text-align:left;vertical-align:middle;overflow-wrap:anywhere}
.reference-table th:last-child,.reference-table td:last-child{border-right:0}
.reference-table thead th{position:sticky;top:0;z-index:2;background:#111b2f;color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.04em;box-shadow:0 1px 0 var(--line2)}
html[data-theme=light] .reference-table thead th{background:#f8fafc}
.keypad-entry-scroll{padding:18px}
.keypad-entry-table{max-width:900px;margin:0 auto;font-size:13px;border:1px solid var(--line);border-radius:14px;overflow:hidden}
