.keypad-entry-table td:not(:first-child){text-align:center;font-weight:750}
.keypad-entry-table kbd{display:inline-grid;min-width:42px;min-height:30px;place-items:center;font-size:12px;color:var(--text);background:rgba(148,163,184,.12)}
.word-library-table{font-size:11.5px}
.word-library-table th,.word-library-table td{padding:5px 7px;line-height:1.25}
.word-library-table th:nth-child(odd),.word-library-table td:nth-child(odd){width:5.5%}
.word-library-table th:nth-child(even),.word-library-table td:nth-child(even){width:11.166%}
.word-library-number{font-variant-numeric:tabular-nums;color:var(--muted);font-weight:800;white-space:nowrap}
@media(max-width:1040px){
