/* v2.09 — precise programming-tree hit areas and visible field-info results. */
/*
  Programming leaves previously used left padding to draw their hierarchy. The
  background therefore started at the branch guide instead of at the actual
  child label. Physically inset the row so hover, active and search states cover
  only the item itself, while the connector remains outside the hit area.
*/
.nav-tree .tree-program-node-leaf > .tree-program-node-link{
  --program-tree-leaf-offset:calc(28px + (var(--tree-depth,1) - 1) * 18px);
  margin-left:var(--program-tree-leaf-offset)!important;
  width:calc(100% - var(--program-tree-leaf-offset))!important;
  max-width:calc(100% - var(--program-tree-leaf-offset))!important;
  padding-left:8px!important;
  overflow:hidden!important;
  background-clip:padding-box!important;
}
.nav-tree .tree-program-node-leaf > .tree-program-node-link::before{
  display:none!important;
}
.nav-tree .tree-program-node-leaf::before{
  content:'';
  position:absolute;
  left:calc((var(--tree-depth,1) - 1) * 18px + 1px);
  top:50%;
  width:27px;
  border-top:1px solid rgba(56,189,248,.52);
  pointer-events:none;
}

/* A yellow ring and dot identify matches located inside the field-information
   panel opened by the i control. */
