  color:var(--text)!important;
  box-shadow:0 0 0 3px color-mix(in srgb,var(--yellow) 30%,transparent)!important;
}
.program-info-toggle.dsc-search-info-match::after{
  content:'';
  position:absolute;
  top:-4px;
  right:-4px;
  width:9px;
  height:9px;
  border-radius:999px;
  background:var(--yellow);
  border:2px solid var(--panel);
  box-sizing:border-box;
  pointer-events:none;
}
html[data-theme="light"] .program-info-toggle.dsc-search-info-match{
