  height:28px!important;
  padding:0 8px!important;
  font-size:9px!important;
}
.pcc2-device-row{height:64px}
.pcc2-fixed-row{height:64px}

/* Category chips must wrap inside their own cell instead of crossing a divider. */
.pcc2-category-chip{
  width:max-content;
  max-width:100%;
  min-height:28px;
  padding:5px 8px;
  align-items:center;
  justify-content:flex-start;
  white-space:normal;
  overflow-wrap:anywhere;
  word-break:normal;
  font-size:8.8px;
  line-height:1.22;
