}
.pcc2-family-summary-toggle .card-collapse-chevron{
  flex:0 0 auto;
}
.pcc2-family-summary-toggle strong{
  display:block;
  min-width:0;
  overflow:visible;
  text-overflow:clip;
  white-space:normal;
  overflow-wrap:anywhere;
  font-size:9.7px;
  line-height:1.22;
}
.pcc2-family-summary-family{
  display:block;
  white-space:normal;
  overflow-wrap:anywhere;
  font-size:9.2px;
  line-height:1.28;
}

/* Instance row: second tree level.  Pseudo-elements form one continuous family spine. */
.pcc2-tree-instance-row{height:56px}
.pcc2-tree-instance-row>td:first-child{
  position:relative;
  overflow:hidden;
}
.pcc2-tree-instance-node{
  position:relative;
  min-height:40px;
  padding-left:40px;
}
.pcc2-tree-instance-branch{
  display:none!important;
}
.pcc2-tree-instance-node::before{
  content:'';
  position:absolute;
  z-index:1;
  left:14px;
  top:-12px;
  bottom:-12px;
  border-left:2px solid var(--pcc-tree-color);
  pointer-events:none;
}
.pcc2-tree-instance-row.is-last .pcc2-tree-instance-node::before{
  bottom:50%;
}
.pcc2-tree-instance-node::after{
  content:'';
  position:absolute;
  z-index:1;
  left:14px;
  top:50%;
  width:21px;
  border-top:2px solid var(--pcc-tree-color);
  pointer-events:none;
}
.pcc2-tree-instance-toggle{
  position:relative;
  z-index:2;
  width:100%!important;
  max-width:100%!important;
  min-height:36px!important;
  height:auto!important;
  padding:5px 8px!important;
  white-space:normal;
  justify-content:flex-start;
}
.pcc2-tree-instance-toggle .card-collapse-chevron{
  flex:0 0 auto;
}
.pcc2-tree-instance-toggle strong{
  min-width:0;
  overflow:visible;
  text-overflow:clip;
  white-space:normal;
  overflow-wrap:anywhere;
  font-size:10px;
  line-height:1.2;
}
.pcc2-instance-circuit,
.pcc2-instance-description{
  gap:4px;
  align-content:center;
}
.pcc2-instance-circuit strong{
  font-size:10.2px;
  line-height:1.2;
}
.pcc2-instance-circuit small{
  font-size:8.7px;
  line-height:1.25;
}
.pcc2-instance-description>span{
  display:block;
  overflow:visible;
  text-overflow:clip;
  white-space:normal;
  overflow-wrap:anywhere;
  font-size:9.5px;
  line-height:1.3;
}
.pcc2-instance-description>div{
  gap:5px;
}
.pcc2-instance-description small{
  min-height:22px;
  padding:3px 7px;
  white-space:normal;
  overflow-wrap:anywhere;
  font-size:8.1px;
  line-height:1.15;
}

/* Child rows: separate family spine and instance spine create the requested tree. */
.pcc2-tree-child-row{height:68px}
.pcc2-tree-child-row>td:first-child{
  position:relative;
  overflow:hidden;
}
.pcc2-tree-child-row.has-next-instance>td:first-child::before{
  content:'';
  position:absolute;
  z-index:1;
  left:24px;
  top:-1px;
  bottom:-1px;
  border-left:2px solid var(--pcc-tree-color);
  pointer-events:none;
}
.pcc2-tree-child{
  position:relative;
  display:block!important;
  min-height:50px;
  padding:0 0 0 56px!important;
}
.pcc2-tree-child>.pcc2-tree-branch{
  display:none!important;
}
.pcc2-tree-child::before{
  content:'';
  position:absolute;
  z-index:1;
  left:39px;
  top:-13px;
  bottom:-13px;
  border-left:2px solid var(--pcc-tree-color);
  pointer-events:none;
}
.pcc2-tree-child.is-last::before{
  bottom:50%;
}
.pcc2-tree-child::after{
  content:'';
  position:absolute;
  z-index:1;
