  align-content:center;
  gap:5px;
  min-width:0;
}
.pcc2-tree-child>div>span{
  color:var(--muted);
  font-size:8.8px!important;
  font-weight:900;
  line-height:1.15;
  white-space:normal;
  overflow-wrap:anywhere;
}
.pcc2-tree-child select,
.pcc2-table tbody tr.pcc2-tree-child-row td:nth-child(2)>select,
.pcc2-table tbody tr.pcc2-tree-child-row td:nth-child(5)>input{
