/* Make the tree geometry deterministic by removing inherited cell padding. */
.pcc2-tree-instance-row>td:first-child,
.pcc2-tree-child-row>td:first-child{
  position:relative!important;
  overflow:visible!important;
  padding:0!important;
  --pcc-tree-main-x:24px;
  --pcc-tree-instance-x:54px;
  --pcc-tree-content-x:84px;
}

/* Main family/device spine: continues through later instances, ending at the last one. */
.pcc2-tree-instance-row>td:first-child::before{
  content:''!important;
  position:absolute!important;
  z-index:0!important;
  left:var(--pcc-tree-main-x)!important;
  top:-1px!important;
  bottom:-1px!important;
  width:0!important;
  height:auto!important;
  border:0!important;
  border-left:2px solid var(--pcc-tree-color)!important;
  pointer-events:none!important;
}
.pcc2-tree-instance-row.is-last>td:first-child::before{bottom:50%!important}

/* Instance elbow and the child-load spine begin at the instance center. */
.pcc2-tree-instance-node{
  position:relative!important;
  display:flex!important;
  align-items:center!important;
  width:100%!important;
  min-height:58px!important;
  height:100%!important;
  padding:0 8px 0 64px!important;
  box-sizing:border-box!important;
}
.pcc2-tree-instance-node::before{
  content:''!important;
  position:absolute!important;
  z-index:0!important;
  left:var(--pcc-tree-main-x)!important;
  top:50%!important;
  width:30px!important;
  height:0!important;
  border:0!important;
  border-top:2px solid var(--pcc-tree-color)!important;
  pointer-events:none!important;
}
.pcc2-tree-instance-node::after{
  content:''!important;
  position:absolute!important;
  z-index:0!important;
  left:var(--pcc-tree-instance-x)!important;
  top:50%!important;
  bottom:-1px!important;
  width:0!important;
  border:0!important;
  border-left:2px solid var(--pcc-tree-color)!important;
  pointer-events:none!important;
}
.pcc2-tree-instance-row.is-collapsed .pcc2-tree-instance-node::after{display:none!important}
.pcc2-tree-instance-branch{display:none!important}
.pcc2-tree-instance-toggle{
  position:relative!important;
  z-index:1!important;
  max-width:100%!important;
  margin:0!important;
}

/* Preserve the main spine while child rows belonging to an earlier instance are shown. */
.pcc2-tree-child-row>td:first-child::before{content:none!important}
.pcc2-tree-child-row.has-next-instance>td:first-child::before{
  content:''!important;
  position:absolute!important;
  z-index:0!important;
  left:var(--pcc-tree-main-x)!important;
  top:-1px!important;
  bottom:-1px!important;
  width:0!important;
  height:auto!important;
  border:0!important;
  border-left:2px solid var(--pcc-tree-color)!important;
  pointer-events:none!important;
}

/* One clean instance spine through its loads, ending at the final child. */
.pcc2-tree-child-row>td:first-child::after{
  content:''!important;
  position:absolute!important;
  z-index:0!important;
  left:var(--pcc-tree-instance-x)!important;
  top:-1px!important;
  bottom:-1px!important;
  width:0!important;
  border:0!important;
  border-left:2px solid var(--pcc-tree-color)!important;
  pointer-events:none!important;
}
.pcc2-tree-child-row.is-last-child>td:first-child::after{bottom:50%!important}

/* Child elbow terminates before the load selector, never under it. */
.pcc2-tree-child{
  position:relative!important;
  display:grid!important;
  align-content:center!important;
  min-height:68px!important;
  padding:0 8px 0 var(--pcc-tree-content-x)!important;
  box-sizing:border-box!important;
}
.pcc2-tree-child::before{
  content:''!important;
  position:absolute!important;
  z-index:0!important;
  left:var(--pcc-tree-instance-x)!important;
  top:50%!important;
  width:24px!important;
  height:0!important;
  border:0!important;
  border-top:2px solid var(--pcc-tree-color)!important;
  pointer-events:none!important;
}
.pcc2-tree-child::after,
.pcc2-tree-child>.pcc2-tree-branch{display:none!important}
.pcc2-tree-child>div{
  position:relative!important;
  z-index:1!important;
  min-width:0!important;
}

