/* v251 — Menu Designer bulk selection, direct delete, and drag-and-drop ordering */
.menu-designer-option-list{
  grid-auto-rows:68px;
}
.menu-designer-option-row{
  position:relative;
  display:grid;
  grid-template-columns:18px 24px minmax(0,1fr) 30px;
  align-items:center;
  gap:6px;
  height:68px;
  min-height:68px;
  padding:0 5px;
  border:1px solid transparent;
  border-radius:13px;
  transition:border-color .12s,background .12s,opacity .12s,transform .12s;
