.label-generator-input-grid{display:grid;grid-template-columns:minmax(340px,1.2fr) minmax(300px,.8fr);gap:10px;align-items:stretch}
.label-generator-entry,.label-generator-final-preview,.label-generator-library-body>label{display:grid;gap:5px;min-width:0}
.label-generator-entry>span,.label-generator-final-preview>span,.label-generator-library-body label>span{font-size:11px;font-weight:900;text-transform:uppercase;letter-spacing:.055em;color:var(--muted)}
.label-generator-entry textarea{min-height:66px;max-height:92px;resize:vertical;padding:9px 11px!important;border-radius:11px!important;font-size:14px}
.label-generator-entry small{font-size:11px;line-height:1.35;color:var(--muted)}
.label-generator-final-preview{padding:9px;border:1px solid var(--line);border-radius:12px;background:rgba(148,163,184,.045)}
.label-generator-lcd{
  width:100%;
  min-width:0;
  display:grid;
  gap:3px;
  padding:10px 12px;
  border:1px solid rgba(6,182,212,.34);
  border-radius:10px;
  background:linear-gradient(180deg,rgba(110,210,235,.88),rgba(61,164,199,.82));
  color:#08212b;
  box-shadow:inset 0 2px 8px rgba(0,0,0,.22);
  font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
  font-size:17px;
  font-weight:800;
  line-height:1.25;
  letter-spacing:.055em;
}
.label-generator-lcd.compact{padding:6px 8px;font-size:11px;border-radius:8px;gap:1px}
.label-generator-lcd-line{display:grid;grid-template-columns:repeat(16,minmax(0,1fr));white-space:nowrap;min-width:0}
.label-generator-lcd-line>span{display:block;text-align:center;min-width:0;border-bottom:2px solid transparent}
.label-generator-lcd-line>span.cursor{border-bottom-color:#08212b}
