.label-generator-options label{display:inline-flex;align-items:center;gap:6px;min-height:30px;padding:0 8px;border:1px solid var(--line);border-radius:9px;background:rgba(148,163,184,.045);font-size:11.5px;font-weight:800;color:var(--text)}
.label-generator-options input[type=checkbox]{width:15px;height:15px;margin:0;padding:0}
.label-generator-options button{min-height:30px!important;height:30px!important;padding:0 9px!important;border-radius:9px!important;font-size:11.5px!important}
.label-generator-count{display:inline-flex;align-items:center;min-height:29px;padding:0 9px;border:1px solid var(--line);border-radius:9px;background:rgba(148,163,184,.055);color:var(--muted);font-size:11px;font-weight:900}
.label-generator-validation{display:flex;align-items:center;gap:8px;margin-top:8px;padding:7px 9px;border-radius:10px;border:1px solid var(--line);font-size:11.5px}
.label-generator-validation strong{white-space:nowrap}.label-generator-validation span{color:var(--muted);line-height:1.35}
.label-generator-validation.success{border-color:rgba(34,197,94,.35);background:rgba(34,197,94,.08)}
.label-generator-validation.error{border-color:rgba(251,113,133,.38);background:rgba(251,113,133,.08)}
.label-generator-match-summary{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-top:6px}
