.label-generator-match-summary>div strong{color:var(--text)}
.label-generator-match-chips{display:flex;gap:4px;flex-wrap:wrap}.label-generator-match-chips span{padding:3px 6px;border-radius:7px;background:rgba(6,182,212,.1);border:1px solid rgba(6,182,212,.18);font-size:10.5px}.label-generator-match-chips b{color:var(--blue)}
