.label-generator-current-empty{margin-top:8px;padding:12px;border:1px dashed var(--line2);border-radius:10px;color:var(--muted);font-size:12px;text-align:center}
.label-generator-library-card,.label-generator-list-card{padding:12px!important;border-radius:15px!important}
.label-generator-library-card>summary{display:flex;align-items:center;gap:8px;cursor:pointer;list-style:none}.label-generator-library-card>summary::-webkit-details-marker{display:none}.label-generator-library-card>summary:before{content:'▸';color:var(--muted);transition:transform .15s}.label-generator-library-card[open]>summary:before{transform:rotate(90deg)}.label-generator-library-card>summary strong{font-size:13px}.label-generator-library-card>summary span{font-size:11px;color:var(--muted)}
