}

/* Each LCD position is made of the character rectangle and a dedicated
   underline strip beneath it, like the physical HS2LCD display. */
.label-generator-lcd-line>span{
  display:grid!important;
  grid-template-rows:minmax(1.45em,auto) 4px!important;
  gap:2px!important;
  align-items:stretch!important;
  min-height:0!important;
  border:0!important;
  border-radius:0!important;
  background:transparent!important;
  box-shadow:none!important;
  line-height:1!important;
  overflow:visible!important;
}
.label-generator-lcd-char{
  display:grid;
  place-items:center;
  width:100%;
  min-width:0;
  min-height:1.45em;
  border:1px solid rgba(8,33,43,.13);
  border-radius:2px;
  background:rgba(255,255,255,.055);
  line-height:1;
}
.label-generator-lcd-underline{
  display:block;
  align-self:start;
  justify-self:center;
  width:58%;
  height:2px;
  border-radius:2px;
  background:transparent;
}
.label-generator-lcd-line>span.cursor-underline::after{
  content:none!important;
  display:none!important;
}
.label-generator-lcd-line>span.cursor-underline .label-generator-lcd-underline{
  background:#08212b;
  box-shadow:0 0 0 1px rgba(8,33,43,.05);
}
.label-generator-lcd-line>span.result-highlight .label-generator-lcd-char{
  background:rgba(255,255,255,.60);
  border-color:rgba(8,33,43,.26);
}
.label-generator-lcd-line>span.lcd-unavailable{
  background:transparent!important;
  border:0!important;
  box-shadow:none!important;
  opacity:.72;
}
.label-generator-lcd-line>span.lcd-unavailable .label-generator-lcd-char{
  background:rgba(71,85,105,.34)!important;
  border-color:rgba(51,65,85,.46)!important;
  box-shadow:inset 0 0 0 1px rgba(255,255,255,.05)!important;
}
.label-generator-lcd-line>span.lcd-unavailable .label-generator-lcd-underline{
  background:transparent!important;
  box-shadow:none!important;
}

/* Give the extra underline strip enough vertical room without changing the
   fixed horizontal cell proportions. */
.label-generator-final-preview .label-generator-lcd,
.label-generator-current-lcd .label-generator-lcd.compact,
.label-generator-step-preview .label-generator-lcd.compact{
  row-gap:3px;
