  padding-left:2px;
  font-size:10.5px;
  line-height:1.1;
}
.label-generator-final-preview .label-generator-line-count span{
  display:inline-block;
}

/* v297 — enforce whole-label two-line capacity while typing */
.label-generator-entry input[data-label-input="single"][data-label-input-limit-hit="true"]{
  outline:2px solid rgba(180,68,68,.30);
