/* v313 — Virtual Keypad progressive initialization and lazy heavy panels. */
.simulator-lazy-panel-note{
  display:flex;
  flex-direction:column;
  gap:4px;
  padding:14px 16px;
  border:1px dashed var(--line,#d5d9e2);
