/* v314 performance containment: large off-screen cards remain in the DOM for
   search/navigation semantics, but the browser can skip their layout/paint
   until they approach the viewport. */
@supports (content-visibility: auto) {
  .programming-top-level-section,
  .module-detail-section,
  .compatible-device-group,
  .comparison-card,
  .knowledge-item,
  .source-card,
  .snippet-card,
  .simulator-config-section,
  .navigation-designer-section,
  .menu-designer-tool-card,
  .menu-designer-option-row,
  .pcc2-section,
  .label-generator-tool-panel {
    content-visibility: auto;
    contain-intrinsic-size: auto 220px;
  }
  .programming-top-level-section { contain-intrinsic-size: auto 360px; }
  .simulator-config-section,
  .navigation-designer-section { contain-intrinsic-size: auto 320px; }
}

