/* v380 — protocol-specific metadata toggle + direction help.
   Keep controls compact, table headers lossless, and direction abbreviations self-explanatory on hover. */
.reporting-table-column-controls,
.reporting-table-metadata-control,
.reporting-table-zero-control{
  display:flex;
  align-items:center;
  gap:5px;
  min-width:0;
}
.reporting-metadata-source-toggle button{
  min-width:34px;
  padding-inline:7px;
  font-weight:950;
}
.reporting-direction-value[title]{
  cursor:help;
  text-decoration-line:underline;
  text-decoration-style:dotted;
  text-decoration-thickness:1px;
  text-underline-offset:3px;
}
.reporting-decoder-table .reporting-description-head,
.reporting-decoder-table .reporting-category-head,
.reporting-decoder-table .reporting-severity-head,
.reporting-decoder-table .reporting-direction-head{
  white-space:nowrap!important;
  overflow:visible!important;
  text-overflow:clip!important;
}
@media(max-width:900px){
  .reporting-table-metadata-control{flex-wrap:wrap}
  .reporting-decoder-table{min-width:1020px!important}
}

/* v380 direction tooltip: immediate, compact help without changing table geometry. */
.reporting-direction-value[data-direction-help]{
  position:relative;
  display:inline-block;
}
.reporting-direction-value[data-direction-help]::after{
  content:attr(data-direction-help);
  position:absolute;
  left:50%;
  bottom:calc(100% + 7px);
  transform:translateX(-50%);
  z-index:120;
  min-width:max-content;
  max-width:260px;
  padding:6px 8px;
  border:1px solid var(--line);
  border-radius:8px;
  background:var(--panel2);
  color:var(--text);
  box-shadow:0 8px 22px rgba(0,0,0,.18);
  font-family:inherit;
  font-size:11px;
  font-weight:800;
  line-height:1.25;
  white-space:nowrap;
  opacity:0;
  visibility:hidden;
  pointer-events:none;
  transition:opacity .08s ease,visibility .08s ease;
}
.reporting-direction-value[data-direction-help]:hover::after,
.reporting-direction-value[data-direction-help]:focus-visible::after{
  opacity:1;
  visibility:visible;
}

/* v382 — Excel-style Reporting Code Decoder field filters + new defaults. */
.reporting-result-filter-panel{
  align-items:stretch;
  flex-direction:column;
  gap:8px;
}
.reporting-filter-field{
  display:inline-flex;
  align-items:center;
  gap:6px;
}
.reporting-filter-badge{
  display:inline-flex;
  align-items:center;
  justify-content:center;
  min-width:18px;
  height:18px;
  padding:0 5px;
  border-radius:999px;
  background:color-mix(in srgb,var(--blue) 20%,var(--panel));
  color:var(--text);
  font-size:9px;
  font-weight:950;
  line-height:1;
}
.reporting-filter-options-row{
  display:flex;
  align-items:flex-start;
  gap:8px;
  padding-top:8px;
  border-top:1px solid var(--line);
  min-width:0;
}
.reporting-filter-options-label{
  flex:0 0 auto;
  padding-top:8px;
  font-size:10px;
  font-weight:900;
  text-transform:uppercase;
  letter-spacing:.05em;
  color:var(--muted);
  white-space:nowrap;
}
.reporting-filter-option-list{
  display:flex;
  align-items:center;
  gap:5px;
  flex-wrap:wrap;
  min-width:0;
  max-height:148px;
  overflow:auto;
  scrollbar-gutter:stable;
  padding:1px 4px 2px 0;
}
.reporting-filter-option{
  flex:0 0 auto;
}
html[data-theme=light] .reporting-filter-badge{background:#dcecf7;color:#0f172a}
@media(max-width:760px){
  .reporting-filter-options-row{display:grid;gap:5px}
  .reporting-filter-options-label{padding-top:0}
  .reporting-result-count{margin-left:0}
}

/* v383 — checklist reporting filters + exact identifier result emphasis. */
.reporting-filter-toolbar{
  display:flex;
  align-items:center;
  gap:10px;
  min-width:0;
}
.reporting-filter-toolbar .reporting-result-count{margin-left:auto}
.reporting-filter-groups{
  display:grid;
  grid-template-columns:repeat(4,minmax(145px,1fr));
  gap:7px;
  min-width:0;
}
.reporting-filter-group{
  min-width:0;
  border:1px solid var(--line);
  border-radius:10px;
  background:var(--panel2);
  overflow:hidden;
}
.reporting-filter-group.has-selection{
  border-color:color-mix(in srgb,var(--blue) 42%,var(--line));
  box-shadow:inset 3px 0 0 color-mix(in srgb,var(--blue) 72%,var(--line));
}
.reporting-filter-group>summary{
  list-style:none;
  display:flex;
  align-items:center;
  gap:7px;
  min-height:34px;
  padding:6px 9px;
  cursor:pointer;
  color:var(--text);
  font-size:11px;
  font-weight:900;
  user-select:none;
}
.reporting-filter-group>summary::-webkit-details-marker{display:none}
.reporting-filter-group>summary:hover{background:color-mix(in srgb,var(--panel2) 88%,var(--blue) 12%)}
.reporting-filter-group>summary .reporting-filter-badge{margin-left:auto}
.reporting-filter-chevron{
  flex:0 0 auto;
  font-size:13px;
  line-height:1;
  color:var(--muted);
  transition:transform .12s ease;
}
.reporting-filter-group[open] .reporting-filter-chevron{transform:rotate(180deg)}
.reporting-filter-group .reporting-filter-option-list{
  display:grid;
  align-content:start;
  gap:1px;
  max-height:180px;
  overflow:auto;
  padding:5px 6px 6px;
  border-top:1px solid var(--line);
  background:color-mix(in srgb,var(--panel) 55%,var(--panel2));
}
.reporting-filter-check{
  display:flex;
  align-items:center;
  gap:7px;
  min-width:0;
  min-height:27px;
  padding:4px 6px;
  border-radius:7px;
  cursor:pointer;
  color:var(--muted);
  font-size:10.5px;
  font-weight:800;
  line-height:1.25;
}
.reporting-filter-check:hover{background:color-mix(in srgb,var(--panel2) 84%,var(--blue) 16%);color:var(--text)}
.reporting-filter-check input{
  position:absolute;
  inline-size:1px;
  block-size:1px;
  opacity:0;
  pointer-events:none;
}
.reporting-filter-check-box{
  position:relative;
  flex:0 0 15px;
  width:15px;
  height:15px;
  border:1px solid color-mix(in srgb,var(--muted) 52%,var(--line));
  border-radius:4px;
  background:var(--panel);
  box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--panel2) 45%,transparent);
}
.reporting-filter-check input:checked+.reporting-filter-check-box{
  border-color:color-mix(in srgb,var(--blue) 76%,var(--line));
  background:color-mix(in srgb,var(--blue) 82%,var(--purple));
}
.reporting-filter-check input:checked+.reporting-filter-check-box::after{
  content:'✓';
  position:absolute;
  inset:0;
  display:grid;
  place-items:center;
  color:#fff;
  font-size:10px;
  font-weight:950;
  line-height:1;
}
.reporting-filter-check input:checked~.reporting-filter-check-label{color:var(--text)}
.reporting-filter-check-all{
  flex:0 0 auto;
  min-height:29px;
  padding:3px 7px;
  border:1px solid var(--line);
  background:var(--panel2);
}
.reporting-filter-check-field-all{
  margin-bottom:3px;
  padding-bottom:6px;
  border-bottom:1px solid var(--line);
  border-radius:6px 6px 0 0;
}
.reporting-filter-check-label{min-width:0;overflow-wrap:anywhere}
.reporting-decoder-table tr.reporting-instance-result-row td{
  background:rgba(251,191,36,.16)!important;
}
.reporting-decoder-table tr.reporting-instance-result-row td:first-child{
  border-left-width:4px!important;
}
.reporting-full-code-hit{white-space:nowrap}
html[data-theme=light] .reporting-filter-group{background:#f7fafc;border-color:#cbd5e1}
html[data-theme=light] .reporting-filter-group .reporting-filter-option-list{background:#fff}
html[data-theme=light] .reporting-filter-check-box{background:#fff;border-color:#94a3b8}
