  border:0!important;
  border-right:var(--dsc-section-chevron-stroke) solid currentColor!important;
  border-bottom:var(--dsc-section-chevron-stroke) solid currentColor!important;
  color:inherit!important;
  font-size:0!important;
  line-height:0!important;
  transform:rotate(-45deg)!important;
  transform-origin:50% 50%!important;
  transition:var(--dsc-section-chevron-motion)!important;
}
