) > summary::before{
  content:""!important;
  box-sizing:border-box!important;
  display:inline-block!important;
  flex:0 0 auto!important;
  width:var(--dsc-section-chevron-size)!important;
  height:var(--dsc-section-chevron-size)!important;
  margin:0 4px 0 1px!important;
  border:0!important;
  border-right:var(--dsc-section-chevron-stroke) solid currentColor!important;
  border-bottom:var(--dsc-section-chevron-stroke) solid currentColor!important;
  border-radius:0!important;
  color:var(--muted)!important;
  background:transparent!important;
  box-shadow:none!important;
  transform:rotate(-45deg)!important;
  transform-origin:50% 50%!important;
  transition:var(--dsc-section-chevron-motion)!important;
}
html body :is(
  .program-note-accordion,
  .program-pgm-template-reference,
  .simulator-config-section,
  .simulator-option-card,
  .simulator-subconfig,
  .menu-designer-ascii-section,
  .menu-designer-tool-card,
  .menu-designer-range-generator,
  .menu-designer-subsection,
  .navigation-option-editor-card,
  .navigation-settings-card,
  .navigation-access-card,
  .navigation-access-subcard,
  .simulator-zone-attributes,
  .label-generator-library-card
)[open] > summary::before{
  transform:rotate(45deg)!important;
}
html body .program-note-accordion > summary::after{content:none!important;display:none!important}

/* Preserve the Reporting Code / Zone Type category reference appearance while
   making its arrow rotation use the same timing as all other section arrows. */
html body :is(:is(#neoReportingCodeDecoder #reporting-tool-table,#powerSeriesReportingCodeDecoder #powerseries-reporting-tool-table),#view-reference #referenceBody:is([data-reference-id="neo-zone-types"],[data-reference-id="new-powerseries-zone-types"],[data-reference-id="neo-wireless-tools"])) .program-style-category > summary::before{
  transition:var(--dsc-section-chevron-motion)!important;
}

@media (prefers-reduced-motion:reduce){
  html body .card-collapse-chevron,
  html body :is(.tree-toggle,.tree-subtoggle,.tree-action-toggle,.tree-program-node-toggle,.collapsible-document-heading) > .chev::before,
  html body :is(#neoReportingCodeDecoder,#powerSeriesReportingCodeDecoder) .reporting-section-toggle-left span,
  html body #newPowerSeriesIconLedEsnTools .icon-led-section-toggle-left span,
  html body :is(#neoReportingCodeDecoder,#powerSeriesReportingCodeDecoder) .reporting-row-expand span,
  html body :is(.program-note-accordion,.program-pgm-template-reference,.simulator-config-section,.simulator-option-card,.simulator-subconfig,.menu-designer-ascii-section,.menu-designer-tool-card,.menu-designer-range-generator,.menu-designer-subsection,.navigation-option-editor-card,.navigation-settings-card,.navigation-access-card,.navigation-access-subcard,.simulator-zone-attributes,.label-generator-library-card) > summary::before,
  html body :is(:is(#neoReportingCodeDecoder #reporting-tool-table,#powerSeriesReportingCodeDecoder #powerseries-reporting-tool-table),#view-reference #referenceBody:is([data-reference-id="neo-zone-types"],[data-reference-id="new-powerseries-zone-types"],[data-reference-id="neo-wireless-tools"])) .program-style-category > summary::before{
