/* v589 — sticky header shield, keypad access hints, enabled-value emphasis */

/* Opaque shield behind the two frozen header rows.  It fills the complete
   60px header stack so scrolled body text can never show through a seam. */
.zone-defaults-v2-grid-header-shield{
  grid-column:1 / span 2!important;
  grid-row:1 / span 2!important;
  position:sticky!important;
  top:0!important;
  left:0!important;
  z-index:115!important;
  width:calc(var(--zone-code-width) + var(--zone-name-width))!important;
  height:60px!important;
  min-height:60px!important;
  max-height:60px!important;
  align-self:start!important;
  justify-self:start!important;
  background:var(--panel2)!important;
  background-clip:border-box!important;
  border-bottom:1px solid var(--line)!important;
  pointer-events:none!important;
}

/* Keep the two left header rows perfectly contiguous. */
.zone-defaults-v2-grid{
  grid-template-rows:32px 28px!important;
}
.zone-defaults-v2-grid-zone-type{
  top:0!important;
  height:32px!important;
  min-height:32px!important;
  max-height:32px!important;
  margin:0!important;
  background:var(--panel2)!important;
}
.zone-defaults-v2-grid-code-head,
.zone-defaults-v2-grid-name-head{
  top:32px!important;
  height:28px!important;
  min-height:28px!important;
  max-height:28px!important;
  margin:0!important;
  background:var(--panel2)!important;
}

/* Attribute 9-16 keypad access hint: press 9 first, then the shown digit. */
.zone-attribute-access-key{
  position:absolute!important;
  top:4px!important;
  right:4px!important;
  display:inline-flex!important;
  align-items:center!important;
  justify-content:center!important;
  min-width:25px!important;
  height:13px!important;
  padding:0 3px!important;
  border:1px solid color-mix(in srgb,var(--line2) 85%,transparent)!important;
  border-radius:4px!important;
  background:var(--panel)!important;
  color:var(--muted)!important;
  font-size:6.5px!important;
  font-weight:850!important;
  line-height:11px!important;
  letter-spacing:0!important;
  white-space:nowrap!important;
  pointer-events:none!important;
}
.zone-defaults-v2-grid-attribute-head,
.zone-attributes-v2-table thead th:not(.zone-attributes-v2-label){
  position:relative!important;
}
.zone-attributes-v2-keypad-note{
  margin-top:-6px!important;
}

/* Y means enabled: highlight only the enabled value/line. N remains plain. */
.zone-defaults-v2-value-row.is-enabled{
