/* v600 — resilient dynamic workspace layout when the left navigation is hidden or resized.
   Grid items are explicitly placed so removing the resizer/sidebar can never auto-place
   the main workspace into a zero-width track. The active workspace always consumes the
   exact space that remains available. */
@media(min-width:1041px){
  .shell{
    width:100%!important;
    max-width:100vw!important;
  }
  .shell>.sidebar{
    grid-column:1!important;
    min-width:0!important;
    max-width:100%!important;
  }
  .shell>.sidebar-resizer{
    grid-column:2!important;
  }
  .shell>.main{
    grid-column:3!important;
    width:100%!important;
    min-width:0!important;
    max-width:100%!important;
  }
  .shell>.main>.topbar,
  .shell>.main>.view.active{
    width:100%!important;
    min-width:0!important;
    max-width:100%!important;
  }
  .shell.sidebar-collapsed{
    grid-template-columns:0 0 minmax(0,1fr)!important;
  }
  .shell.sidebar-collapsed>.sidebar,
  .shell.sidebar-collapsed>.sidebar-resizer{
    display:none!important;
  }
  .shell.sidebar-collapsed>.main{
    grid-column:1 / -1!important;
    width:100%!important;
    max-width:100%!important;
    min-width:0!important;
  }
  body.sidebar-collapsed .workspace-loading-progress{
    left:0!important;
