  height:50%!important;
  border:0!important;
  border-left:1px solid var(--workspace-menu-tree-line)!important;
  border-bottom:1px solid var(--workspace-menu-tree-line)!important;
}

/* v632 — unified hierarchy connectors and stable Programming-tree rows.
   Two separate tree renderers are used in the workspace: the left Programming
   navigation and the Programming document outline.  Keep their geometry
   independent, but use the same rules: one rail per parent, one elbow per row,
   and the rail terminates at the centre of the parent's final child. */

/* ---------- Left navigation Programming tree ---------- */
#leftTree{
  --workspace-hierarchy-line:color-mix(in srgb,var(--blue) 34%,var(--line2));
  --workspace-program-icon:color-mix(in srgb,var(--purple) 42%,var(--muted));
