  transform:none!important;
  pointer-events:none!important;
}
#leftTree .tree-program-entry > .tree-subchildren > .tree-program-node,
#leftTree .tree-program-node-children > .tree-program-node{
  position:relative!important;
}
#leftTree .tree-program-entry > .tree-subchildren > .tree-program-node:not(:last-child)::after,
#leftTree .tree-program-node-children > .tree-program-node:not(:last-child)::after{
  content:""!important;
  display:block!important;
  position:absolute!important;
  z-index:0!important;
  left:-14px!important;
  top:0!important;
  bottom:0!important;
  width:0!important;
  border-left:1px solid var(--workspace-hierarchy-line)!important;
  pointer-events:none!important;
}
#leftTree .tree-program-entry > .tree-subchildren > .tree-program-node:last-child:not(.tree-program-node-leaf) > .tree-program-node-row::before,
#leftTree .tree-program-node-children > .tree-program-node:last-child:not(.tree-program-node-leaf) > .tree-program-node-row::before,
#leftTree .tree-program-entry > .tree-subchildren > .tree-program-node:last-child.tree-program-node-leaf::before,
#leftTree .tree-program-node-children > .tree-program-node:last-child.tree-program-node-leaf::before{
  left:-14px!important;
  top:0!important;
  width:9px!important;
  height:50%!important;
  border:0!important;
  border-left:1px solid var(--workspace-hierarchy-line)!important;
  border-bottom:1px solid var(--workspace-hierarchy-line)!important;
}
/* Old per-link/depth connector implementations must stay off. */
#leftTree .tree-program-node-link::after{
  /* ::after is reserved for search-result badges by newer search rules. */
}
#leftTree .tree-program-node-children::before{
  display:none!important;
