#documentBody[data-programming-key] .program-block.is-open > .program-children::before,
#documentBody[data-programming-key] .program-fold.is-open > .program-fold-expanded::before,
#documentBody[data-programming-key] :is(.program-children,.program-fold-expanded,.program-fold-lazy-children)::before{
