  left:calc((var(--depth,0) * var(--indent-step,28px)) - 12px)!important;
  top:0!important;
  bottom:0!important;
  width:0!important;
  border-left:1px solid var(--workspace-program-tree-line)!important;
  background:none!important;
  pointer-events:none!important;
}
#documentBody[data-programming-key] :is(.program-children,.program-fold-expanded,.program-fold-lazy-children)
  > .program-row:has(~ :is(.program-block,.program-fold,.program-row))
  > .program-guide:not(.empty)::before{
  content:""!important;
  display:block!important;
  position:absolute!important;
  z-index:1!important;
  left:9px!important;
  top:0!important;
  bottom:0!important;
  width:0!important;
  border-left:1px solid var(--workspace-program-tree-line)!important;
  background:none!important;
  pointer-events:none!important;
}
/* Leaf field-information panels are siblings of their row rather than children
   of a wrapper. When one is open on a non-final leaf, continue the parent rail
   through that panel so expanding details cannot break the tree line. */
#documentBody[data-programming-key] .program-field-info:not([hidden]):has(~ :is(.program-block,.program-fold,.program-row))::after{
  content:""!important;
  display:block!important;
  position:absolute!important;
  z-index:1!important;
  left:-110px!important;
  top:-6px!important;
  bottom:-12px!important;
  width:0!important;
  border-left:1px solid var(--workspace-program-tree-line)!important;
  background:none!important;
  pointer-events:none!important;
}
@media(max-width:900px){
