}
#documentBody[data-programming-key] :is(.program-children,.program-fold-expanded,.program-fold-lazy-children)
  > :is(.program-block,.program-fold):not(.workspace-section-results-only-hidden-v617):not(.programming-local-search-hidden):not(.dsc-search-hidden):not(:has(~ :is(.program-block,.program-fold,.program-row):not(.workspace-section-results-only-hidden-v617):not(.programming-local-search-hidden):not(.dsc-search-hidden)))
  > .program-row > .program-guide:not(.empty) .guide-v,
#documentBody[data-programming-key] :is(.program-children,.program-fold-expanded,.program-fold-lazy-children)
  > .program-row:not(.workspace-section-results-only-hidden-v617):not(.programming-local-search-hidden):not(.dsc-search-hidden):not(:has(~ :is(.program-block,.program-fold,.program-row):not(.workspace-section-results-only-hidden-v617):not(.programming-local-search-hidden):not(.dsc-search-hidden)))
  > .program-guide:not(.empty) .guide-v{
  display:block!important;
  left:9px!important;
  top:-1px!important;
  bottom:50%!important;
  width:1px!important;
  border-radius:0!important;
  background:var(--workspace-program-tree-line)!important;
  box-shadow:none!important;
}
#documentBody[data-programming-key] :is(.program-children,.program-fold-expanded,.program-fold-lazy-children)
  > .program-row:not(.workspace-section-results-only-hidden-v617):not(.programming-local-search-hidden):not(.dsc-search-hidden):not(:has(~ :is(.program-block,.program-fold,.program-row):not(.workspace-section-results-only-hidden-v617):not(.programming-local-search-hidden):not(.dsc-search-hidden)))
  > .program-guide:not(.empty)::before{
  display:none!important;
  content:none!important;
}

/* v636 — always-obvious menu hover + staged workspace activity/progress. */
#leftTree.nav-tree :is(.tree-toggle,.tree-subtoggle,.tree-link,.tree-program-node-link,.tree-program-document-link):hover,
#leftTree.nav-tree .tree-action-row:hover > .tree-link{
  background:color-mix(in srgb,var(--blue) 12%,var(--panel2))!important;
  box-shadow:inset 3px 0 0 color-mix(in srgb,var(--blue) 72%,transparent), inset 0 0 0 1px color-mix(in srgb,var(--blue) 18%,transparent)!important;
  color:var(--text)!important;
