}
.workspace-loading-progress span{
  width:var(--workspace-loading-value)!important;
  min-width:18px;
  transform:none!important;
  transition:width .16s cubic-bezier(.2,.7,.2,1)!important;
  background:linear-gradient(105deg,var(--purple) 0%,var(--blue) 46%,color-mix(in srgb,var(--blue) 35%,white) 56%,var(--blue) 68%,var(--purple) 100%)!important;
  background-size:220% 100%!important;
