  .workspace-loading-progress span{animation:none!important;transition:width .08s linear!important}
}

/* v637 — searched-menu hover must win over the v624 search-state
   neutralization. Use deliberately higher specificity so every navigable row
   visibly reacts to the pointer whether Workspace Search is active or not. */
#leftTree#leftTree#leftTree#leftTree :is(.tree-toggle,.tree-subtoggle,.tree-link,.tree-program-node-link,.tree-program-document-link):hover,
