  z-index:70!important;
  background:var(--workspace-sticky-opaque,var(--panel))!important;
  backdrop-filter:none!important;
  box-shadow:0 1px 0 var(--line)!important;
}
#documentBody[data-programming-presentation="compact-summary-table"][data-programming-presentation="compact-summary-table"] :is(.program-block.is-open:not(.program-category),.program-fold.is-open) > .program-row[data-program-toggle]:hover{
  background:var(--workspace-sticky-opaque,var(--panel))!important;
}
#documentBody[data-programming-presentation="compact-summary-table"][data-programming-presentation="compact-summary-table"] :is(.program-block.is-open:not(.program-category),.program-fold.is-open) > .program-row[data-program-toggle]:has(.program-info-toggle.active){
