  box-shadow:inset 2px 0 0 color-mix(in srgb,var(--blue) 72%,transparent),0 1px 0 var(--line)!important;
}

/* v652 — Programming v4.62 New group/ungroup control in the tree gutter.
   The grouped range row itself stays visible (for example,
   "1-5  Function Key 1-5 Assignment"). Only the small icon is overlaid in
   the existing left gutter. Ungrouping hides that grouped summary and reveals
   the five normal sibling rows without shifting their layout. */
#documentBody[data-programming-presentation="compact-summary-table"][data-programming-presentation="compact-summary-table"] .program-group-fold{
  position:relative!important;
  overflow:visible!important;
}
#documentBody[data-programming-presentation="compact-summary-table"][data-programming-presentation="compact-summary-table"] .program-group-fold > .program-fold-gutter-rail{
  position:sticky!important;
  top:var(--program-compact-gutter-sticky-top,54px)!important;
  z-index:78!important;
  /* v654 — give the sticky rail the same vertical footprint as the gutter
     button, then cancel that footprint with a matching negative margin.
     This keeps the control inside the grouped range bounds while scrolling,
     so it no longer drops below the last child row or below the grouped
     summary row when the fold is closed. */
  height:38px!important;
  min-height:38px!important;
  margin:0 0 -38px!important;
  overflow:visible!important;
  pointer-events:none!important;
}
#documentBody[data-programming-presentation="compact-summary-table"][data-programming-presentation="compact-summary-table"] .program-group-fold > .program-fold-gutter-rail > .program-fold-gutter-toggle{
  position:absolute!important;
  top:7px!important;
  left:calc((var(--depth,0) * var(--indent-step,28px)) - 22px)!important;
  z-index:1!important;
  box-sizing:border-box!important;
  display:flex!important;
  align-items:center!important;
  justify-content:center!important;
  width:24px!important;
  min-width:24px!important;
  max-width:24px!important;
  height:24px!important;
  min-height:24px!important;
  margin:0!important;
  padding:0!important;
  border:1px solid color-mix(in srgb,var(--blue) 30%,var(--line))!important;
  border-radius:6px!important;
  background:var(--workspace-sticky-opaque,var(--panel))!important;
  color:var(--muted)!important;
  box-shadow:0 1px 2px rgba(15,23,42,.08)!important;
  cursor:pointer!important;
  pointer-events:auto!important;
}
#documentBody[data-programming-presentation="compact-summary-table"][data-programming-presentation="compact-summary-table"] .program-group-fold > .program-fold-gutter-rail > .program-fold-gutter-toggle:hover{
  background:color-mix(in srgb,var(--blue) 10%,var(--workspace-sticky-opaque,var(--panel)))!important;
  border-color:color-mix(in srgb,var(--blue) 58%,var(--line))!important;
  color:var(--text)!important;
}
#documentBody[data-programming-presentation="compact-summary-table"][data-programming-presentation="compact-summary-table"] .program-group-fold > .program-fold-gutter-rail > .program-fold-gutter-toggle:focus-visible{
  outline:2px solid var(--blue)!important;
  outline-offset:2px!important;
}
#documentBody[data-programming-presentation="compact-summary-table"][data-programming-presentation="compact-summary-table"] .program-group-fold > .program-fold-gutter-rail > .program-fold-gutter-toggle .program-fold-regroup{
  display:flex!important;
  align-items:center!important;
